                    new_w = w[:i] + c + w[i+1:]
                    if new_w in word_set:
                        neighbors.append(new_w)
        return neighbors

    def bfs_distance(start_node, end_node, word_set):
        if start_node == end_node:
            return 0
        queue = deque([(start_node, 0)])
        visited = {start_node}
        while queue:
            current, dist = queue.popleft()
            for neighbor in get_neighbors(current):
                if neighbor == end_node:
                    return dist + 1
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, dist + 1))
        return float('inf')

    def bfs_path(start_node, end_node, word_set):
        if start_node == end_node:
            return [start_node]
        queue = deque([(start_node, [start_node])])
        visited = {start_node}
        while queue:
            current, path = queue.popleft()
            for neighbor in get_neighbors(current):
                if neighbor == end_node:
                    return path + [neighbor]
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, path + [neighbor]))
        return None

    initial_dist = bfs_distance(start, end, word_set)
    if initial_dist == float('inf'):
        print("0")
        print("-1")
        return

    best_word = "0"
    min_steps = initial_dist

    # Strategy: Iterate through all words in the dictionary and try adding them.
    # Since N <= 1000, N^2 is 1,000,000, which is acceptable.
    # For each candidate word 'w', we check if adding it creates a shorter path.
    # The new path would be: start -> ... -> w -> ... -> end.
    # We need dist(start, w) + 1 + dist(w, end) < min_steps.

